function frame(now){requestAnimationFrame(frame);const frameTime=(now-last)/1000,wall=Math.min(.05,frameTime);last=now;controllerButtons();const active=started&&!inspectionHeld&&state.phase!=='paused'&&state.phase!=='results';const playbackRate=auto?verificationRate:1;if(active){accumulator+=wall*playbackRate;while(accumulator>=1/60){const before=state.phase,countBefore=Math.ceil(state.countdown);stepRace(state,auto?(state.verifyPark?parkMasteryInput(state,state.racers[0]):state.verifyWipeout?wipeoutVerificationInput():state.mode==='versus'?state.racers.map(r=>verificationInput(state,r)):verificationInput(state,state.racers[0])):input(),1/60);if(before==='countdown'&&Math.ceil(state.countdown)!==countBefore)audio.signal(state.phase==='running'?'go':'countdown');clock=state.time;accumulator-=1/60;if(isVerify&&(state.verifyWipeout||state.verifyIceBalance)&&!state.wipeoutInspected&&state.racers[0].wipeout?.elapsed>.4){state.wipeoutInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'wipeout',time:state.time,pose:wipeoutPose(state.racers[0].wipeout),speed:state.racers[0].speed});break;}if(isVerify&&state.verifyWeeds&&!state.weedsInspected&&state.course.id==='reed'){const r=state.racers[0];if(state.time>10&&state.course.resistance.some(p=>Math.hypot(r.x-p.x,r.z-p.z)<16)){state.weedsInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'Drake weed beds',time:state.time,count:state.course.resistance.length,misses:r.misses,weedDrag:r.weedDrag});break;}}if(isVerify&&state.verifyPosts&&!state.postsInspected&&state.course.id==='reed'){const r=state.racers[0];if(r.x>26&&r.x<62&&r.z>98&&r.z<122){state.postsInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'Drake post passage',time:state.time,lap:r.lap,misses:r.misses,collision:r.collision,next:r.next});break;}}if(isVerify&&state.verifyMoorings&&!state.mooringsInspected){const r=state.racers[0],b=state.course.mooredBoats?.[0];if(b&&state.time>10&&Math.hypot(r.x-b.x,r.z-b.z)<43){state.mooringsInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'moored launches',time:state.time,misses:r.misses,count:state.course.mooredBoats.length});break;}}if(isVerify&&state.verifyRollers&&!state.rollersInspected){const r=state.racers[0],train=state.course.waveTrain;if(train&&Math.abs(r.x-train[0])<28&&r.z>train[1]+4&&r.z<train[1]+12){state.rollersInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'three rollers',time:state.time,misses:r.misses,hullY:r.hydro.y,waterY:r.hydro.waterHeight,load:r.hydro.load});break;}}if(isVerify&&state.verifyBalls&&!state.ballsInspected&&state.time>4){const balls=state.course.rocks.filter(o=>o.type==='ball'),r=state.racers[0];if(balls.length&&Math.min(...balls.map(o=>Math.hypot(o.x-r.x,o.z-r.z)))<45){state.ballsInspected=true;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'metal cluster',time:state.time,count:balls.length,misses:r.misses});break;}}if(isVerify&&state.verifyPierSurface&&!state.pierSurfaceInspected&&state.racers[0].pierSurface?.stage===(state.course.reverse?5:3)&&state.racers[0].z>158&&state.racers[0].z<164&&state.racers[0].hydro.y+1.1<.65){state.pierSurfaceInspected=true;inspectionHeld=true;accumulator=0;const r=state.racers[0];$('verifyStatus').textContent=JSON.stringify({inspection:'low-tide pier',time:state.time,lap:r.lap,misses:r.misses,speed:r.speed*3.6,hullY:r.hydro.y,diveRemaining:r.hydro.diveRemaining});break;}if(isVerify&&state.verifyPierDive&&!state.pierDiveInspected&&state.racers[0].pierDiveStage===1&&state.racers[0].z>158&&state.racers[0].z<164&&state.racers[0].hydro.y+1.1<.65){state.pierDiveInspected=true;inspectionHeld=true;accumulator=0;const r=state.racers[0];$('verifyStatus').textContent=JSON.stringify({inspection:'pier dive',time:state.time,lap:r.lap,misses:r.misses,speed:r.speed*3.6,hullY:r.hydro.y,diveRemaining:r.hydro.diveRemaining});break;}if(isVerify&&inspectPier&&state.course.id==='amber'){const r=state.racers[0],b=state.course.crossbars.find(b=>Math.abs(r.x-b.x)<b.length/2&&Math.abs(r.z-b.z)<1&&r.hydro.y+1.1<b.bottom);if(b){inspectPier=false;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'Sunset pier passage',time:state.time,lap:r.lap,misses:r.misses,hullY:r.hydro.y,deckBottom:b.bottom,collision:r.collision});break;}}if(isVerify&&inspectPier&&state.course.id==='tempest'&&state.racers[0].x< -30&&state.racers[0].z>110){inspectPier=false;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent='Pier approach held at '+state.time.toFixed(3)+' s';break;}if(isVerify&&inspectIce&&state.racers[0].onIce){const r=state.racers[0];inspectIce=false;inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:'ice slide',sheet:r.onIce,time:state.time,y:r.hydro.y,wet:r.hydro.wet,speed:r.speed*3.6});break;}if(isVerify&&inspectAtPassage&&state.course.passage){const p=state.course.passage,r=state.racers[0],geometry=p.structurePath||p.path,a=geometry[0],b=geometry.at(-1),dx=b.x-a.x,dz=b.z-a.z,along=((r.x-a.x)*dx+(r.z-a.z)*dz)/(dx*dx+dz*dz),across=Math.abs((r.x-a.x)*dz-(r.z-a.z)*dx)/Math.hypot(dx,dz);if((p.kind!=='gate'||r.lap>1)&&along>(p.kind==='jump-dive'?.485:.27)&&along<(p.kind==='jump-dive'?.51:.35)&&across<p.width){inspectionHeld=true;inspectAtPassage=false;$('verifyStatus').textContent='Inspection held at '+state.time.toFixed(3)+' s / lap '+r.lap+(p.kind==='jump-dive'?' / hull y '+r.hydro.y.toFixed(2)+' m / dive '+r.hydro.diveRemaining.toFixed(2)+' s':'');accumulator=0;break;}}if(isVerify&&inspectJump){const r=state.racers[0],h=r.hydro,v=state.mode==='practice'?r.playgroundVerification:(r.rampInspection||={});if(state.mode!=='practice'){if(h.onRamp){v.contact=true;v.landing=h.landingId;}if(v.contact&&h.landingId>v.landing)v.landed=true;}if(v?.contact&&((inspectJump==='apex'&&h.airborne&&h.vy<.4&&h.y-h.waterHeight>(state.mode==='practice'?2:.5))||(inspectJump==='landing'&&v.landed&&h.compression>.12))){inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({inspection:inspectJump,time:state.time,height:h.y-h.waterHeight,compression:h.compression,load:h.load,wet:h.wet,speed:r.speed*3.6,fov:camera.fov});inspectJump='';break;}}if(isVerify&&state.mode==='practice'&&state.racers[0].playgroundVerification?.done){const r=state.racers[0];inspectionHeld=true;accumulator=0;$('verifyStatus').textContent=JSON.stringify({phase:'Free ride landing verified',time:state.time,wallSeconds:(performance.now()-verificationWallStart)/1000,rate:playbackRate,quality,fps:Math.round(lastFPS),...r.playgroundVerification,rings:r.stunt.rings,score:r.stunt.score});break;}if(before!=='results'&&state.phase==='results')result();}}else if(!started)clock+=wall;visual(state.phase==='paused'||inspectionHeld?0:wall*playbackRate);frameSum+=frameTime;frames++;adapt+=wall;if(adapt>5){lastFPS=frames/frameSum;if($('quality').value==='auto'&&frames/frameSum<48&&quality!=='low')setQuality(quality==='high'?'medium':'low');frames=0;frameSum=0;adapt=0;}}
let appliedGraphics=null;function applySavedSettings(){audio.setOptions(saved.audio);$('sound').checked=saved.audio.enabled;for(const key of ['graphics','laps','seaState'])$(key==='graphics'?'quality':key).value=String(saved.preferences[key]);if(appliedGraphics!==saved.preferences.graphics){setQuality(saved.preferences.graphics==='auto'?'high':saved.preferences.graphics);appliedGraphics=saved.preferences.graphics;}state.seaState=saved.preferences.seaState;
 document.querySelectorAll('[data-rider]').forEach(b=>b.querySelector('strong').textContent=riderName(Number(b.dataset.rider)));for(const o of $('secondRider').options)o.textContent=riderName(Number(o.value));selectRider(selectedRider);$('secondRider').value=String(saved.versus?.rider??1);for(const key of ['Engine','Grip','Handling'])$('second'+key).value=saved.versus?.tune?.[key.toLowerCase()]??0;$('handicap').checked=!!saved.versus?.handicap;$('swapColours').checked=!!saved.versus?.swapColours;
 if(!isVerify&&selectedDifficulty>saved.unlocked){selectedDifficulty=saved.unlocked;$('difficulty').value=String(selectedDifficulty);}if(!isVerify&&selectedMode!=='practice'&&!saved.reached.includes(selectedCourse))selectedCourse='greyhaven';refreshCourses();}
